fn next(seed: i32) -> i32 {
    let mut h: i32 = seed * 1103515245 + 12345;
    h = (h >> 13) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn pick(seed: i32, lo: i32, hi: i32) -> i32 {
    lo + next(seed) % (hi - lo + 1)
}

fn mix(a: i32, b: i32) -> i32 {
    next(a * 31 + b)
}

fn dims() -> i32 {
    (256 << 16) | 128
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "LIB PRNG", 0xffffff, 2);
    host::display::draw_string(8, 30, "NEXT PICK MIX", 0x00ff66, 1);
    let mut i: i32 = 0;
    while i < 32 {
        host::display::set_pixel(pick(i * 2, 8, 248), pick(i * 2 + 1, 48, 120), 0xffff00);
        i = i + 1;
    }
    host::display::present();
}
